    S1 = #{if_absent => F@_3},
    S2 = if F@_1 == '$undef' -> S1;
            true -> S1#{key => F@_1}
         end,
    if F@_2 == '$undef' -> S2;
       true -> S2#{value => F@_2}
    end;
