read_group(Bin, FieldNum) ->
    {NumBytes, EndTagLen} = read_gr_b(Bin, 0, 0, 0, 0, FieldNum),
    <<Group:NumBytes/binary, _:EndTagLen/binary, Rest/binary>> = Bin,
    {Group, Rest}.

%% Like skipping over fields, but record the total length,
%% Each field is <(FieldNum bsl 3) bor FieldType> ++ <FieldValue>
%% Record the length because varints may be non-optimally encoded.
%%
%% Groups can be nested, but assume the same FieldNum cannot be nested
%% because group field numbers are shared with the rest of the fields
%% numbers. Thus we can search just for an group-end with the same
%% field number.
%%
%% (The only time the same group field number could occur would
%% be in a nested sub message, but then it would be inside a
%% length-delimited entry, which we skip-read by length.)
read_gr_b(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen, FieldNum)
  when N < (32-7) ->
    read_gr_b(Tl, N+7, X bsl N + Acc, NumBytes, TagLen+1, FieldNum);
read_gr_b(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen,
          FieldNum) ->
    Key = X bsl N + Acc,
    TagLen1 = TagLen + 1,
    case {Key bsr 3, Key band 7} of
        {FieldNum, 4} -> % 4 = group_end
            {NumBytes, TagLen1};
        {_, 0} -> % 0 = varint
            read_gr_vi(Tl, 0, NumBytes + TagLen1, FieldNum);
        {_, 1} -> % 1 = bits64
            <<_:64, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 8, 0, FieldNum);
        {_, 2} -> % 2 = length_delimited
            read_gr_ld(Tl, 0, 0, NumBytes + TagLen1, FieldNum);
        {_, 3} -> % 3 = group_start
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 4} -> % 4 = group_end
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 5} -> % 5 = bits32
            <<_:32, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 4, 0, FieldNum)
    end.

read_gr_vi(<<1:1, _:7, Tl/binary>>, N, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_vi(Tl, N+7, NumBytes+1, FieldNum);
read_gr_vi(<<0:1, _:7, Tl/binary>>, _, NumBytes, FieldNum) ->
    read_gr_b(Tl, 0, 0, NumBytes+1, 0, FieldNum).

read_gr_ld(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_ld(Tl, N+7, X bsl N + Acc, NumBytes+1, FieldNum);
read_gr_ld(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum) ->
    Len = X bsl N + Acc,
    NumBytes1 = NumBytes + 1,
    <<_:Len/binary, Tl2/binary>> = Tl,
    read_gr_b(Tl2, 0, 0, NumBytes1 + Len, 0, FieldNum).

merge_msgs(Prev, New, MsgName) when is_atom(MsgName) -> merge_msgs(Prev, New, MsgName, []).

merge_msgs(Prev, New, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        key -> merge_msg_key(Prev, New, TrUserData);
        value -> merge_msg_value(Prev, New, TrUserData);
        put_request -> merge_msg_put_request(Prev, New, TrUserData);
        put_response -> merge_msg_put_response(Prev, New, TrUserData);
        get_request -> merge_msg_get_request(Prev, New, TrUserData);
        get_response -> merge_msg_get_response(Prev, New, TrUserData);
        delete_request -> merge_msg_delete_request(Prev, New, TrUserData);
        delete_response -> merge_msg_delete_response(Prev, New, TrUserData)
    end.

-compile({nowarn_unused_function,merge_msg_key/3}).
merge_msg_key(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{channel := NFchannel}} -> S1#{channel => NFchannel};
             {#{channel := PFchannel}, _} -> S1#{channel => PFchannel};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{identifier := NFidentifier}} -> S2#{identifier => NFidentifier};
             {#{identifier := PFidentifier}, _} -> S2#{identifier => PFidentifier};
             _ -> S2
         end,
    case {PMsg, NMsg} of
        {_, #{msg_uuid := NFmsg_uuid}} -> S3#{msg_uuid => NFmsg_uuid};
        {#{msg_uuid := PFmsg_uuid}, _} -> S3#{msg_uuid => PFmsg_uuid};
        _ -> S3
    end.

-compile({nowarn_unused_function,merge_msg_value/3}).
merge_msg_value(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{json_payload := NFjson_payload}} -> S1#{json_payload => NFjson_payload};
             {#{json_payload := PFjson_payload}, _} -> S1#{json_payload => PFjson_payload};
             _ -> S1
         end,
    case {PMsg, NMsg} of
        {_, #{stored_at := NFstored_at}} -> S2#{stored_at => NFstored_at};
        {#{stored_at := PFstored_at}, _} -> S2#{stored_at => PFstored_at};
        _ -> S2
    end.

-compile({nowarn_unused_function,merge_msg_put_request/3}).
merge_msg_put_request(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {#{key := PFkey}, #{key := NFkey}} -> S1#{key => merge_msg_key(PFkey, NFkey, TrUserData)};
             {_, #{key := NFkey}} -> S1#{key => NFkey};
             {#{key := PFkey}, _} -> S1#{key => PFkey};
             {_, _} -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {#{value := PFvalue}, #{value := NFvalue}} -> S2#{value => merge_msg_value(PFvalue, NFvalue, TrUserData)};
             {_, #{value := NFvalue}} -> S2#{value => NFvalue};
             {#{value := PFvalue}, _} -> S2#{value => PFvalue};
             {_, _} -> S2
         end,
    case {PMsg, NMsg} of
        {_, #{if_absent := NFif_absent}} -> S3#{if_absent => NFif_absent};
        {#{if_absent := PFif_absent}, _} -> S3#{if_absent => PFif_absent};
        _ -> S3
    end.

-compile({nowarn_unused_function,merge_msg_put_response/3}).
merge_msg_put_response(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{created := NFcreated}} -> S1#{created => NFcreated};
             {#{created := PFcreated}, _} -> S1#{created => PFcreated};
             _ -> S1
         end,
    case {PMsg, NMsg} of
        {#{value := PFvalue}, #{value := NFvalue}} -> S2#{value => merge_msg_value(PFvalue, NFvalue, TrUserData)};
        {_, #{value := NFvalue}} -> S2#{value => NFvalue};
        {#{value := PFvalue}, _} -> S2#{value => PFvalue};
        {_, _} -> S2
    end.

-compile({nowarn_unused_function,merge_msg_get_request/3}).
merge_msg_get_request(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {#{key := PFkey}, #{key := NFkey}} -> S1#{key => merge_msg_key(PFkey, NFkey, TrUserData)};
        {_, #{key := NFkey}} -> S1#{key => NFkey};
        {#{key := PFkey}, _} -> S1#{key => PFkey};
        {_, _} -> S1
    end.

-compile({nowarn_unused_function,merge_msg_get_response/3}).
merge_msg_get_response(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {#{value := PFvalue}, #{value := NFvalue}} -> S1#{value => merge_msg_value(PFvalue, NFvalue, TrUserData)};
        {_, #{value := NFvalue}} -> S1#{value => NFvalue};
        {#{value := PFvalue}, _} -> S1#{value => PFvalue};
        {_, _} -> S1
    end.

-compile({nowarn_unused_function,merge_msg_delete_request/3}).
merge_msg_delete_request(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    case {PMsg, NMsg} of
