    end.


verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        key -> v_msg_key(Msg, [MsgName], TrUserData);
        value -> v_msg_value(Msg, [MsgName], TrUserData);
        put_request -> v_msg_put_request(Msg, [MsgName], TrUserData);
        put_response -> v_msg_put_response(Msg, [MsgName], TrUserData);
        get_request -> v_msg_get_request(Msg, [MsgName], TrUserData);
        get_response -> v_msg_get_response(Msg, [MsgName], TrUserData);
        delete_request -> v_msg_delete_request(Msg, [MsgName], TrUserData);
        delete_response -> v_msg_delete_response(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


-compile({nowarn_unused_function,v_submsg_key/3}).
-dialyzer({nowarn_function,v_submsg_key/3}).
v_submsg_key(Msg, Path, TrUserData) -> v_msg_key(Msg, Path, TrUserData).

-compile({nowarn_unused_function,v_msg_key/3}).
-dialyzer({nowarn_function,v_msg_key/3}).
v_msg_key(#{} = M, Path, TrUserData) ->
    case M of
        #{channel := F1} -> v_type_string(F1, [channel | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{identifier := F2} -> v_type_string(F2, [identifier | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{msg_uuid := F3} -> v_type_string(F3, [msg_uuid | Path], TrUserData);
        _ -> ok
    end,
    lists:foreach(fun (channel) -> ok;
                      (identifier) -> ok;
                      (msg_uuid) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
v_msg_key(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), key}, M, Path);
v_msg_key(X, Path, _TrUserData) -> mk_type_error({expected_msg, key}, X, Path).

-compile({nowarn_unused_function,v_submsg_value/3}).
-dialyzer({nowarn_function,v_submsg_value/3}).
v_submsg_value(Msg, Path, TrUserData) -> v_msg_value(Msg, Path, TrUserData).

-compile({nowarn_unused_function,v_msg_value/3}).
-dialyzer({nowarn_function,v_msg_value/3}).
v_msg_value(#{} = M, Path, TrUserData) ->
    case M of
        #{json_payload := F1} -> v_type_string(F1, [json_payload | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{stored_at := F2} -> v_type_int64(F2, [stored_at | Path], TrUserData);
        _ -> ok
    end,
    lists:foreach(fun (json_payload) -> ok;
                      (stored_at) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
v_msg_value(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), value}, M, Path);
v_msg_value(X, Path, _TrUserData) -> mk_type_error({expected_msg, value}, X, Path).

-compile({nowarn_unused_function,v_msg_put_request/3}).
-dialyzer({nowarn_function,v_msg_put_request/3}).
v_msg_put_request(#{} = M, Path, TrUserData) ->
    case M of
        #{key := F1} -> v_submsg_key(F1, [key | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{value := F2} -> v_submsg_value(F2, [value | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{if_absent := F3} -> v_type_bool(F3, [if_absent | Path], TrUserData);
        _ -> ok
    end,
    lists:foreach(fun (key) -> ok;
                      (value) -> ok;
                      (if_absent) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
v_msg_put_request(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), put_request}, M, Path);
v_msg_put_request(X, Path, _TrUserData) -> mk_type_error({expected_msg, put_request}, X, Path).

-compile({nowarn_unused_function,v_msg_put_response/3}).
-dialyzer({nowarn_function,v_msg_put_response/3}).
v_msg_put_response(#{} = M, Path, TrUserData) ->
    case M of
