v_msg_put_response(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), put_response}, M, Path);
v_msg_put_response(X, Path, _TrUserData) -> mk_type_error({expected_msg, put_response}, X, Path).

-compile({nowarn_unused_function,v_msg_get_request/3}).
-dialyzer({nowarn_function,v_msg_get_request/3}).
v_msg_get_request(#{} = M, Path, TrUserData) ->
    case M of
